pragma solidity ^0.8.0;

contract TextRegistry {
    string[] private texts;
    event textAdded(string hash);
    event textRemoved(string hash);

    function addtext(string memory hash) public {
        texts.push(hash);
        emit textAdded(hash);
    }

    function removetext(string memory hash) public {
        for (uint i = 0; i < texts.length; i++) {
            if (keccak256(bytes(texts[i])) == keccak256(bytes(hash))) {
                for (uint j = i; j < texts.length - 1; j++) {
                    texts[j] = texts[j + 1];
                }
                texts.pop();
                emit textRemoved(hash);
                return;
            }
        }
    }

    function gettexts() public view returns (string[] memory) {
        return texts;
    }
}
